add_action('rest_api_init', function () {
    register_rest_route('tfsc-priority-check/v1', '/term', [
        'methods'=>'GET',
        'permission_callback'=>function () { return current_user_can('manage_options'); },
        'callback'=>function () {
            $term=get_term(701,'beroep_functienaam');
            if (is_wp_error($term)) { return $term; }
            $raw=get_term_meta(701,'archive_featured_image',true);
            $pod=function_exists('pods')?pods('beroep_functienaam',701):null;
            $value=$pod?$pod->field('archive_featured_image'):null;
            $summarize=function ($value) {
                if (is_scalar($value) || null===$value) { return $value; }
                if (is_array($value)) {
                    return ['keys'=>array_keys($value),'ID'=>$value['ID']??null,'id'=>$value['id']??null,
                        'first_ID'=>is_array($value[0]??null)?($value[0]['ID']??$value[0]['id']??null):($value[0]??null)];
                }
                return ['type'=>gettype($value)];
            };
            return rest_ensure_response(['term_id'=>701,'taxonomy'=>$term->taxonomy,'raw'=>$summarize($raw),'pods'=>$summarize($value)]);
        },
    ]);
});

add_action('rest_api_init', function () {
    register_rest_route('tfsc-priority-check/v1', '/purge', [
        'methods'=>'POST',
        'permission_callback'=>function () { return current_user_can('manage_options'); },
        'callback'=>function () {
            $terms=get_terms(['hide_empty'=>false,'meta_key'=>'archive_featured_image','number'=>250]);
            if (is_wp_error($terms)) { return $terms; }
            $urls=[];
            foreach ($terms as $term) {
                $value=get_term_meta($term->term_id,'archive_featured_image',true);
                if (empty($value)) { continue; }
                $url=get_term_link($term);
                if (is_wp_error($url)) { continue; }
                do_action('litespeed_purge_url',$url); $urls[]=$url;
            }
            return rest_ensure_response(['purged_archive_urls'=>$urls]);
        },
    ]);
});
